<?php// Database migration script to add image_path column to bulletin_posts table// Database connection$host = 'localhost';$dbname = 'd394711_main';$username = 'root';$password = '';try {    $pdo = new PDO("mysql:host=$host;port=3306;dbname=$dbname", $username, $password);    $pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);    // Check if image_path column already exists    $stmt = $pdo->query("SHOW COLUMNS FROM bulletin_posts LIKE 'image_path'");    $columnExists = $stmt->rowCount() > 0;    if (!$columnExists) {        // Add image_path column        $sql = "ALTER TABLE bulletin_posts ADD COLUMN image_path VARCHAR(255) NULL AFTER content";        $pdo->exec($sql);        echo "Successfully added image_path column to bulletin_posts table.";    } else {        echo "image_path column already exists in bulletin_posts table.";    }} catch (PDOException $e) {    echo "Error: " . $e->getMessage();}?>